// Baseline security headers for responses that pass through Pages Functions.
//
// Cloudflare applies public/_headers to static-asset responses, but documents that it does NOT apply
// them to responses generated by Functions. The middleware therefore adds any of these that are
// missing, so a page is never served without its protections whichever path produced it.
//
// Single source of truth: these values must match the `/*` block in public/_headers exactly.
// build.sh compares the two and fails the build if they drift.

export const SECURITY_HEADERS = {
  "Strict-Transport-Security": "max-age=63072000; includeSubDomains",
  "Content-Security-Policy": "default-src 'self'; script-src 'self' https://static.cloudflareinsights.com 'report-sample'; style-src 'self'; img-src 'self' data:; font-src 'self'; media-src 'self'; connect-src 'self' https://cloudflareinsights.com; frame-src 'none'; worker-src 'none'; manifest-src 'self'; frame-ancestors 'none'; base-uri 'self'; form-action 'none'; object-src 'none'; require-trusted-types-for 'script'; trusted-types 'none'; upgrade-insecure-requests; report-uri /api/report; report-to csp",
  "Reporting-Endpoints": "csp=\"/api/report\"",
  "X-Content-Type-Options": "nosniff",
  "X-Frame-Options": "DENY",
  "Referrer-Policy": "strict-origin-when-cross-origin",
  "Permissions-Policy": "accelerometer=(), autoplay=(self), browsing-topics=(), camera=(), display-capture=(), encrypted-media=(), fullscreen=(self), geolocation=(), gyroscope=(), hid=(), magnetometer=(), microphone=(), midi=(), payment=(), publickey-credentials-get=(), screen-wake-lock=(), serial=(), usb=(), xr-spatial-tracking=()",
  "Cross-Origin-Opener-Policy": "same-origin",
  "Cross-Origin-Embedder-Policy": "require-corp",
  "Cross-Origin-Resource-Policy": "same-origin",
  "X-Permitted-Cross-Domain-Policies": "none",
  "Origin-Agent-Cluster": "?1",
};

// Paths whose static rules deliberately drop the page CSP (PDFs render in the browser's own viewer).
const NO_CSP = [/^\/assets\/docs\//, /^\/assets\/Jayant-Goswami-Resume\.pdf$/];

/** Adds every baseline header the response doesn't already carry. Never overrides an existing value. */
export function applySecurityHeaders(headers, pathname) {
  const skipCsp = NO_CSP.some((re) => re.test(pathname));
  for (const [name, value] of Object.entries(SECURITY_HEADERS)) {
    if (skipCsp && name === "Content-Security-Policy") continue;
    if (!headers.has(name)) headers.set(name, value);
  }
}
